//go:build ignore

// Copy into upstream converter/xlsx and run TestCodexXLSXStrings.
package xlsx
import("archive/zip";"bytes";"encoding/json";"math/rand";"os";"path/filepath";"testing")
func TestCodexXLSXStrings(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"basic.xlsx","features.xlsx","form-fixed.xlsx","form-pages.xlsx","form-rows.xlsx","math.xlsx","print.xlsx"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(984123));fragments:=[]string{`<si><t>hello</t></si>`,`<si><t>日本語</t></si>`,`<si><r><t>one </t></r><r><t>two</t></r></si>`,`<si><t>A_x000D__x000A_B</t></si>`,`<si><r><rPr><b/></rPr><t>bold</t></r><r><t> plain</t></r></si>`,`<si><t> &amp; &#xA9; </t><rPh><t>ignored</t></rPh></si>`,`<si/>`,`<si><r><t/></r><t>_x005F_x000A_</t></si>`,`<ignored><si><t>wrong</t></si></ignored>`};for i:=0;i<1200;i++{var b bytes.Buffer;z:=zip.NewWriter(&b);add:=func(name,content string){f,e:=z.Create(name);if e!=nil{t.Fatal(e)};f.Write([]byte(content))};add("xl/workbook.xml",`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"/>`);if i%11!=0 {add("xl/_rels/workbook.xml.rels",`<Relationships><Relationship Id="rId1" Type="x/sharedStrings" Target="sharedStrings.xml"/></Relationships>`);s:=`<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">`;for j:=0;j<r.Intn(12);j++{s+=fragments[r.Intn(len(fragments))]};s+="</sst>";if i%17==0{s=s[:len(s)-2]};add("xl/sharedStrings.xml",s)};if e:=z.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))};out:=[]any{};for _,data:=range samples{c,_,e:=openWorkbook(bytes.NewReader(data),int64(len(data)),&Options{NoSystemFonts:true,SystemFonts:true});if e!=nil{t.Fatal(e)};want:=[]string{};for _,v:=range c.sst{want=append(want,v.plain)};out=append(out,map[string]any{"input":data,"want":want})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/xlsx/strings.json"),b,0644);e!=nil{t.Fatal(e)}}
